define :lemon_clamp_value do |value, low, high|
  [[value.to_f, low].max, high].min
end

define :lemon_approach_value do |current, target, amount|
  current.to_f + ((target.to_f - current.to_f) * amount.to_f)
end

define :lemon_wait_until_playing do
  while (get(:playing) != true) or (get(:active_piece) != :lemon)
    sync :aiot_tick
  end
end

define :lemon_wait_music_beats do |beats|
  remaining=[beats.to_f, 0.0].max
  while remaining>0.0001
    if (get(:playing) == true) and (get(:active_piece) == :lemon)
      use_bpm get(:lemon_current_bpm).to_f
      step=[remaining, 1.0].min
      sleep step
      remaining=remaining-step
    else
      sync :aiot_tick
    end
  end
end

define :lemon_layer_enabled_for_role do |role|
  if role==:melody
    get(:lemon_layer_melody)==true
  elsif role==:harmony
    get(:lemon_layer_harmony)==true
  elsif role==:bass
    get(:lemon_layer_bass)==true
  else
    get(:lemon_layer_rhythm)==true
  end
end

