define :lemon_play_voice_event do |role, note_value, duration, velocity, source|
  if (lemon_layer_enabled_for_role role) and (get(:active_piece) == :lemon)
    synth_name, role_amp, release_scale, transpose, pan_value=lemon_voice_config role, source
    release_value=[[duration.to_f*release_scale.to_f, 0.05].max, 6.0].min
    use_synth synth_name
    amp_value=lemon_clamp_value(velocity, 0.04, 1.0)*role_amp.to_f*get(:lemon_master_amp).to_f
    if note_value.respond_to?(:map)
      played_notes=note_value.map {|value| value.to_i+transpose.to_i}
    else
      played_notes=note_value.to_i+transpose.to_i
    end
    play played_notes,
         attack: 0.005,
         release: release_value,
         amp: amp_value,
         pan: pan_value.to_f
  end
end

define :lemon_play_rhythm_event do |note_value, velocity|
  if (get(:lemon_layer_rhythm) == true) and (get(:active_piece) == :lemon)
    style=get(:lemon_current_style)
    drum_note_values=note_value.respond_to?(:map) ? note_value : [note_value]
    drum_note_values.each do |midi_value|
      midi_note=midi_value.to_i
      if style==:modern_pop
        if [35, 36].include?(midi_note)
          sample_name=:elec_soft_kick
        elsif [38, 40].include?(midi_note)
          sample_name=:elec_hi_snare
        elsif [42, 44].include?(midi_note)
          sample_name=:elec_tick
        else
          sample_name=:elec_cymbal
        end
        style_amp=0.34
        cutoff_value=114
      elsif style==:lofi_night
        if [35, 36].include?(midi_note)
          sample_name=:bd_tek
        elsif [38, 40].include?(midi_note)
          sample_name=:sn_dub
        elsif [42, 44].include?(midi_note)
          sample_name=:drum_cymbal_closed
        else
          sample_name=:drum_tom_mid_soft
        end
        style_amp=0.20
        cutoff_value=82
      else
        if [35, 36].include?(midi_note)
          sample_name=:bd_haus
        elsif [38, 40].include?(midi_note)
          sample_name=:sn_dub
        elsif [42, 44].include?(midi_note)
          sample_name=:drum_cymbal_closed
        elsif [46, 49, 52, 55, 57].include?(midi_note)
          sample_name=:drum_cymbal_open
        else
          sample_name=:drum_tom_mid_soft
        end
        if style==:acoustic_ballad
          style_amp=0.22
          cutoff_value=94
        else
          style_amp=0.43
          cutoff_value=120
        end
      end
      amp_value=lemon_clamp_value(velocity, 0.04, 1.0)*style_amp*get(:lemon_master_amp).to_f
      sample sample_name, amp: amp_value, cutoff: cutoff_value
    end
  end
end

define :lemon_perform_event_track do |events, role, total_beats|
  cursor=0.0
  events.each do |event|
    start_beat, duration, note_value, velocity, source=event
    lemon_wait_music_beats start_beat.to_f-cursor
    lemon_wait_until_playing
    if role==:rhythm
      lemon_play_rhythm_event note_value, velocity
    else
      lemon_play_voice_event role, note_value, duration, velocity, source
    end
    cursor=start_beat.to_f
  end
  lemon_wait_music_beats total_beats.to_f-cursor
end

