live_loop :lemon_parameter_smoother do
  use_real_time
  set :lemon_current_bpm, lemon_approach_value(get(:lemon_current_bpm), get(:lemon_target_bpm), 0.22)
  set :lemon_master_amp, lemon_approach_value(get(:lemon_master_amp), get(:lemon_target_master_amp), 0.28)
  sleep 0.25
end

live_loop :lemon_music_beat_reporter do
  lemon_wait_until_playing
  use_bpm get(:lemon_current_bpm).to_f
  beat_count=get(:lemon_beat_count).to_i
  if beat_count<lemon_pickup_beats
    beat_number=beat_count+1
    bar_number=0
  else
    beat_number=((beat_count-lemon_pickup_beats)%4)+1
    bar_number=1+((beat_count-lemon_pickup_beats)/4)
  end
  strength=beat_number==1 ? 1.0 : 0.45
  osc "/music/beat", bar_number, beat_number, get(:lemon_current_bpm).to_f, strength
  if beat_number==1
    set :lemon_bar_count, bar_number
    osc "/music/bar", bar_number, "lemon"
  end
  set :lemon_beat_count, (beat_count+1)%lemon_loop_beats
  lemon_wait_music_beats 1.0
end

live_loop :lemon_state_reporter do
  use_real_time
  lemon_report_state
  osc "/music/style", "lemon", get(:lemon_current_style).to_s if get(:active_piece) == :lemon
  lemon_report_layers
  sleep 0.5
end

live_loop :lemon_lemon_melody do
  lemon_perform_event_track lemon_melody_events, :melody, lemon_loop_beats
end

live_loop :lemon_lemon_harmony do
  lemon_perform_event_track lemon_harmony_events, :harmony, lemon_loop_beats
end

live_loop :lemon_lemon_bass do
  lemon_perform_event_track lemon_bass_events, :bass, lemon_loop_beats
end

live_loop :lemon_lemon_rhythm do
  lemon_perform_event_track lemon_rhythm_events, :rhythm, lemon_loop_beats
end
